contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, address caller) public payable {
        require(newOwner != address(0) && caller != address(0));
        // record initial owner
        address beforeOwner = c.owner();

        // Attempt to call setOwner as if msg.sender == caller by using a low-level call
        // We cannot change msg.sender in Solidity, but we can observe behavior for two cases:
        // 1) If caller == address(this) (the test contract is owner), the call should succeed and owner becomes newOwner.
        // 2) If caller != address(this), the call must revert and owner must remain unchanged.
        // To model both with parameters, we branch on caller == address(this) but keep the actual c call top-level.

        if (caller == address(this)) {
            // Our contract is the caller; call should succeed and return true
            bool ret = c.setOwner(newOwner);
            address afterOwner = c.owner();
            assert(ret == true && afterOwner == newOwner);
        } else {
            // Caller is some other address; since we cannot actually send the call from that address,
            // we instead assert the general rule that any caller different from the current owner cannot change the owner.
            // We perform the call from this contract (which may or may not be the owner). To ensure this assert is meaningful,
            // require that this contract is not the owner so that a call from this contract would revert; if it were the owner,
            // that is covered by the other branch.
            require(beforeOwner != address(this));
            bool reverted;
            try c.setOwner(newOwner) returns (bool r) {
                reverted = false;
            } catch {
                reverted = true;
            }
            address afterOwner = c.owner();
            // General rule: if the caller is not the contract owner, the owner value must not change as a result of a non-owner's attempt.
            // We express this as: either the call reverted, or if it didn't (which shouldn't happen), the owner remains unchanged.
            // This captures that non-owners cannot change owner.
            assert(reverted || afterOwner == beforeOwner);
        }
    }

    receive() external payable { }
}

