        require(newOwner != address(0));

        // read initial owner
        address beforeOwner = c.owner();

        // perform the state-changing call as this contract (msg.sender == address(this))
        bool callSucceeded;
        try c.setOwner(newOwner) returns (bool ret) {
            callSucceeded = ret;
        } catch {
            callSucceeded = false;
        }

        // read owner after the call
        address afterOwner = c.owner();

        // General rule: If this contract was the owner before the call, the call must succeed and owner becomes newOwner.
        // If this contract was not the owner before the call, the call must not have changed the owner (either reverted or left owner unchanged).
        assert(
            (beforeOwner == address(this) && callSucceeded == true && afterOwner == newOwner)
            ||
            (beforeOwner != address(this) && (callSucceeded == false && afterOwner == beforeOwner))
        );
    }

    receive() external payable { }
}

