contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address candidateNewOwner, address caller) public payable {
        // No precondition
        // Read the owner before attempting change
        address ownerBefore = c.owner();

        // We need to attempt calling setOwner as if msg.sender == caller.
        // Since the checker calls run with this contract as msg.sender for calls to c,
        // we cannot change msg.sender. Instead, we simulate two scenarios by
        // branching on whether the InvMutTest contract is currently the owner.
        // The general rule: only the current owner can change owner; if call succeeds
        // then the owner becomes candidateNewOwner; otherwise it stays ownerBefore.

        bool reverted;
        // Try to call setOwner; it will succeed only if address(this) == ownerBefore
        try c.setOwner(candidateNewOwner) returns (bool ok) {
            reverted = false;
            // ok should be true per function return
            // read owner after successful call
            address ownerAfter = c.owner();
            // If the call did not revert, owner must have been changed to candidateNewOwner
            assert(ownerAfter == candidateNewOwner);
            // Also the function should have returned true
            assert(ok == true);
        } catch {
            reverted = true;
            // read owner after revert
            address ownerAfter = c.owner();
            // If it reverted, owner must remain unchanged
            assert(ownerAfter == ownerBefore);
        }

        // Final general assertion: either the call reverted and owner unchanged,
        // or it succeeded and owner equals candidateNewOwner.
        // This is already enforced by the asserts above but include a final combined check
        // to satisfy the requirement of a single assert at the end of the function.
        // Compute owner now
        address ownerNow = c.owner();
        assert((reverted && ownerNow == ownerBefore) || (!reverted && ownerNow == candidateNewOwner));
    }
    receive() external payable { }
}

