    constructor(C _c) { c = _c; }

    // single public test function taking inputs: callerIsOwner indicates whether
    // we will simulate a call from the owner by first ensuring this contract is the owner
    // (when true), and newOwner is the address to set. amount is unused but included
    // to demonstrate parameterization (not required here).
    function run(bool makeThisOwner, address newOwner, uint256 /*amount*/) public payable {
        require(true);

        // If requested, ensure this test contract is the owner by calling setOwner from the deploying address.
        // The fresh C was deployed with owner = msg.sender (the deployer). The checker deploys a fresh C
        // and passes it to this test's constructor; msg.sender for that deployment is the external deployer,
        // not this test. But this test can become owner only if the current owner (external deployer) calls setOwner.
        // We cannot make external deployer act here, so only possible owner we can be is the initial owner if
        // the checker deployed this test as the owner — however per the spec the checker deploys c fresh and runs
        // run with InvMutTest as msg.sender for calls. To make a meaningful general property we instead observe
        // behavior for both cases by attempting the call and recording whether it reverted.

        // Read owner before the call
        address ownerBefore = c.owner();

        bool reverted;
        bool ret;
        // Attempt to call setOwner from this contract (msg.sender == address(this))
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            ret = success;
        } catch {
            reverted = true;
            ret = false;
        }

        address ownerAfter = c.owner();

        // General rule asserted:
        // - If the call did not revert, then msg.sender (this contract) must have been the ownerBefore,
        //   the call must have returned true, and ownerAfter equals newOwner.
        // - If the call reverted, then ownerAfter must equal ownerBefore (no state change), and the call did not return true.
        assert(
            (!reverted && ownerBefore == address(this) && ret == true && ownerAfter == newOwner)
            || (reverted && ownerAfter == ownerBefore && ret == false)
        );
    }

    receive() external payable { }
}

