    function run(address callerLike, address newOwner) public payable {
        require(true);

        // read owner before the attempt
        address ownerBefore = c.owner();

        // attempt to call setOwner as this contract (which is the deployer of c and thus the initial owner)
        // but we want to model both cases: when msg.sender (this contract) is the owner and when not.
        // To simulate a call from a non-owner, we check callerLike: if callerLike equals ownerBefore,
