        // However because every call to c from this test contract has msg.sender == address(this),
        // we cannot change the EVM caller. Instead we express the general rule relative to whether
        // ownerBefore equals address(this): when address(this) == ownerBefore the call must succeed and
        // owner becomes newOwner; otherwise the call must revert and owner remains ownerBefore.

        bool didRevert;
        try c.setOwner(newOwner) returns (bool ok) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        address ownerAfter = c.owner();

        // General rule: if this contract was the owner before the call, the call must not revert and ownerAfter == newOwner.
        // If this contract was not the owner before the call, the call must revert and ownerAfter == ownerBefore.
        assert(
            (address(this) == ownerBefore && !didRevert && ownerAfter == newOwner) ||
            (address(this) != ownerBefore && didRevert && ownerAfter == ownerBefore)
        );
    }

