contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes a candidate new owner and a flag indicating whether
    // this contract should attempt the setOwner call as the owner or not. Since the checker
    // deploys a fresh C with owner = msg.sender (the deployer), and here msg.sender for C's
    // constructor was this InvMutTest contract, InvMutTest is the initial owner of c.
    function run(address candidate, bool callAsOwner) public payable {
        require(address(c) != address(0));

        // read owner before the call
        address ownerBefore = c.owner();

        bool reverted;
        // If callAsOwner is true, we (this contract) call setOwner() as owner (we are initial owner).
        // If false, we simulate a non-owner call by using a low-level call with a forged sender
        // impossible in solidity here; instead, we simulate by first transferring ownership away
        // to some other address (candidate) and then attempting setOwner which should revert.

        if (callAsOwner) {
            // We are initially owner (InvMutTest deployed c). Calling setOwner should succeed and return true.
            bool ok = c.setOwner(candidate);
            reverted = false;
            // record final owner
            address ownerAfter = c.owner();
            // When owner calls setOwner, it should set owner to the candidate and return true.
            assert(ok == true && ownerAfter == candidate);
            return; // assert above is the required single assert for this branch; but to satisfy template
        } else {
            // transfer ownership away first so that this contract is no longer owner
            // transfer to candidate so that subsequent call by this contract should revert
            bool okTransfer = c.setOwner(candidate);
            require(okTransfer == true);

            // confirm we are no longer owner
            address ownerNow = c.owner();
            require(ownerNow == candidate);

            // attempt to call setOwner again as non-owner; it should revert. We catch revert.
            try c.setOwner(address(0)) {
                reverted = false;
            } catch {
                reverted = true;
            }

            // final owner after the failed attempt
            address ownerAfter = c.owner();

            // General rule asserted: if a non-owner calls setOwner it must revert and owner must be unchanged.
            assert(reverted == true && ownerAfter == ownerNow);
        }
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params:
    //   address candidate - an address to set as new owner
    //   bool makeNonOwner - if true, first transfer ownership away so the subsequent call is from a non-owner
    function run(address candidate, bool makeNonOwner) public payable {
        require(address(c) != address(0));

        // read owner before any operations
        address ownerBefore = c.owner();

        // If we need to make the caller a non-owner for the decisive call, transfer ownership away now.
        // This call is a top-level state-changing call on c.
        if (makeNonOwner) {
            c.setOwner(candidate);
        }

        // Attempt the decisive call and record whether it reverted and any returned boolean.
        bool reverted;
        bool ret;
        // We cannot put the call inside try/catch in a nested manner that violates the rule — try/catch is allowed
        // but the state-changing call must be top-level. We therefore perform the call via try/catch at top-level.
        try c.setOwner(candidate) returns (bool ok) {
            reverted = false;
            ret = ok;
        } catch {
            reverted = true;
            ret = false;
        }

        // read owner after the decisive call
        address ownerAfter = c.owner();

        // General rule: if the decisive caller was the ownerBefore (i.e., we did not transfer away),
        // then the call must succeed (not reverted), return true, and ownerAfter equals candidate.
        // If the decisive caller was not the ownerBefore (i.e., we transferred away), then the call must revert
        // and ownerAfter must equal the owner seen just before the decisive call (which is candidate because
        // we transferred ownership to it when makeNonOwner==true).
        address expectedOwnerBeforeDecisive = makeNonOwner ? candidate : ownerBefore;
        bool wasDecisiveCallerOwner = (expectedOwnerBeforeDecisive == ownerBefore);

        assert(
            (wasDecisiveCallerOwner && reverted == false && ret == true && ownerAfter == candidate)
            || (!wasDecisiveCallerOwner && reverted == true && ownerAfter == expectedOwnerBeforeDecisive)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function
    // Params:
    //   address candidate - address to pass to setOwner for the decisive call
    //   bool firstCallByOwner - if true, the first top-level setOwner call will be made by the current owner (msg.sender == owner);
    //                         if false, the first call will be made when this contract is not the owner (we arrange that by first transferring ownership away)
    function run(address candidate, bool firstCallByOwner) public payable {
        require(address(c) != address(0));

        // Read owner before any state-changing calls
        address ownerBefore = c.owner();

        // We will perform at most two top-level state-changing calls on c, each as its own statement.
        // If firstCallByOwner is false, we first transfer ownership away so that the decisive call is by a non-owner.
        if (!firstCallByOwner) {
            // This call is top-level and will be executed by this contract (which is the owner, since it deployed c).
            // Transfer ownership to candidate so this contract is no longer the owner.
            c.setOwner(candidate);
        }

        // Now perform the decisive call and capture whether it reverts and any returned value.
        bool reverted;
        bool ret;
        try c.setOwner(candidate) returns (bool ok) {
            reverted = false;
            ret = ok;
        } catch {
            reverted = true;
            ret = false;
        }

        // Read owner after the decisive call
        address ownerAfter = c.owner();

        // Determine whether the decisive call was made by the owner that was present immediately before that call.
        // If we did not transfer away, the decisive caller is the original owner (ownerBefore). If we transferred away,
        // the decisive caller is not the original owner (so it should have reverted and ownerAfter should equal candidate).
        bool decisiveCallerWasOwner = firstCallByOwner;

        // General rule:
        // - If the decisive caller was the owner, the call must not revert, must return true, and owner becomes candidate.
